import boto3

def stream_completion(prompt):
    client = boto3.client('bedrock-runtime')

    response = client.invoke_model(
        model_id='amazon.bedrock.model',
        body={
            'prompt': prompt,
            'max_tokens': 150
        }
    )

    response_body = response['body'].read()
    response_json = json.loads(response_body)

    for token in response_json['completion']:
        yield token

import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError

bedrock_client = boto3.client('bedrock-runtime')

def answer_with_context(question, context):
    try:
        response = bedrock_client.invoke_model(
            model_id='amazon.bedrock.<model_id>',
            body={
                'prompt': f'Answer the following question using the provided context: {question}\n\nContext: {context}',
                'max_tokens': 150
            }
        )
        result = response['body'].read()
        return result.decode('utf-8')
    except (NoCredentialsError, PartialCredentialsError) as e:
        return f'Error: {e}'

import boto3

def extract_json(text):
    bedrock = boto3.client('bedrock-runtime')
    model_id = 'amazon.titan-text-express-v1'
    payload = {
        'inputText': text,
        'textGenerationConfig': {
            'maxTokenCount': 4096,
            'temperature': 0,
            'topP': 0.9
        }
    }
    response = bedrock.invoke_model(
        body=json.dumps(payload),
        modelId=model_id,
        accept='application/json',
        contentType='application/json'
    )
    result = json.loads(response['body'].read())
    return result.get('outputText', '')

if __name__ == '__main__':\n    text = 'Sample text to extract JSON from.'
